import { overlay } from '~/shared/lib/overlay';

export type TermProps = {
  contents: string;
};

export const Term = (props: TermProps) => {
  const handleClick = () => {
    overlay.closeAll();
  };
  return (
    <div className="modal full on">
      <div className="modal-top">
        <h2>약관보기</h2>
        <button type="button" className="btn close-btn" onClick={handleClick}>
          <span>닫기</span>
        </button>
      </div>
      <div className="modal-body whitespace-pre-line break-words">{props?.contents}</div>
    </div>
  );
};
